function hslToHex(h, s, l) {
  s /= 100;
  l /= 100;
  const k = (n) => (n + h / 30) % 12;
  const a = s * Math.min(l, 1 - l);
  const f = (n) =>
    l - a * Math.max(-1, Math.min(k(n) - 3, Math.min(9 - k(n), 1)));
  return (
    "#" +
    [f(0), f(8), f(4)]
      .map((x) =>
        Math.round(x * 255)
          .toString(16)
          .padStart(2, "0")
      )
      .join("")
  );
}

/**
 * Generates a unique, visually distinct color for any given string key.
 * This function is scalable and will produce different colors for a large number of inputs.
 * @param {string} key - The unique identifier for the item (e.g., "2025-09-05 - Throw 1").
 * @returns {string} A hex color string (e.g., "#e63946").
 */
export const generateUniqueColor = (key) => {
  // 1. Create a numeric hash from the string key to get a consistent starting point.
  let hash = 0;
  for (let i = 0; i < key.length; i++) {
    hash = key.charCodeAt(i) + ((hash << 5) - hash);
    hash = hash & hash; // Ensure it's a 32bit integer
  }

  // 2. Use the golden ratio to generate well-spaced, deterministic hues.
  // This is the key to creating visually distinct colors that don't clash.
  const goldenRatioConjugate = 0.61803398875;
  const hueSeed = Math.abs(hash) / 2 ** 32; // Normalize hash to a value between 0 and 1
  const hue = ((hueSeed + goldenRatioConjugate) % 1) * 360;

  // 3. Use fixed saturation and lightness for vibrant, consistent colors.
  const saturation = 85; // Vibrant but not overly harsh
  const lightness = 55; // Bright enough to stand out on the dark chart background

  // 4. Convert the HSL color to a HEX string and return it.
  return hslToHex(hue, saturation, lightness);
};
